To compare two Excel files and show discrepancies in Node.js, you can use a combination of libraries such as `xlsx` for reading Excel files and `lodash` for comparing arrays. Here's a basic example:

First, install the necessary dependencies:

```bash
npm install xlsx lodash
```

Then, create a script to compare the files:

```javascript
const XLSX = require('xlsx');
const _ = require('lodash');

function compareExcelFiles(file1, file2, callback) {
  const workbook1 = XLSX.readFile(file1);
  const workbook2 = XLSX.readFile(file2);

  const sheet_name_list1 = workbook1.SheetNames;
  const sheet_name_list2 = workbook2.SheetNames;

  const sheetNames = _.intersection(sheet_name_list1, sheet_name_list2);

  const discrepancies = [];

  sheetNames.forEach(sheetName => {
    const data1 = XLSX.utils.sheet_to_json(workbook1.Sheets[sheetName]);
    const data2 = XLSX.utils.sheet_to_json(workbook2.Sheets[sheetName]);

    const rows = _.zip(data1, data2);

    rows.forEach(([row1, row2], index) => {
      const isEqual = _.isEqual(row1, row2);
      if (!isEqual) {
        discrepancies.push({
          sheetName,
          rowIndex: index + 1,
          row1,
          row2,
        });
      }
    });
  });

  callback(discrepancies);
}

// Usage
compareExcelFiles('file1.xlsx', 'file2.xlsx', (discrepancies) => {
  console.log(discrepancies);
});
```

This script reads the Excel files, compares the sheets with the same name, and finds discrepancies in the rows. The callback function is called with an array of objects, each object containing the sheet name, row index, and the two rows that are different.

You can adjust the script to handle different file names, sheet names, and comparison logic as needed.

